"""Locations of the KOTOR 2 world, read from data/locations.json (generated by tools/build_world_data.py from the research tables)."""
import json
import pkgutil
import typing


class LocationData(typing.NamedTuple):
    id: int
    name: str
    type: str
    spec: dict          # everything the client needs to detect the check
    requires: typing.Tuple[typing.Tuple[str, int], ...]   # (family, tokens needed) pairs, all of which must hold
    progression: bool
    only_if_option: str


# "Telos>=3 NarShaddaa>=2" -> family key -> item name
FAMILY_KEYS = {
    "Telos": "Telos Progression",
    "NarShaddaa": "Nar Shaddaa Progression",
    "DxunOnderon": "Dxun/Onderon Progression",
    "Dantooine": "Dantooine Progression",
    "Korriban": "Korriban Progression",
    "Endgame": "Endgame Progression",
}


def _parse_requires(text: str) -> typing.Tuple[typing.Tuple[str, int], ...]:
    out = []
    for part in text.split():
        key, _, n = part.partition(">=")
        out.append((FAMILY_KEYS[key], int(n)))
    return tuple(out)


def _load() -> typing.Tuple[typing.List[LocationData], dict]:
    data = json.loads(pkgutil.get_data(__name__, "data/locations.json").decode("utf-8"))
    locs = []
    for l in data["locations"]:
        spec = {k: v for k, v in l.items() if k not in ("id", "name", "requires", "progression", "only_if_option")}
        locs.append(LocationData(l["id"], l["name"], l["type"], spec, _parse_requires(l.get("requires", "")), bool(l["progression"]),
                                 l.get("only_if_option", "")))
    return locs, data


LOCATIONS, _RAW = _load()
LEVEL_MAX = _RAW["level_max"]
LOCATION_NAME_TO_ID = {l.name: l.id for l in LOCATIONS}
VICTORY_LOCATION = "Defeat Kreia"
